import os,sys,json,hashlib,time,subprocess,fcntl
from pathlib import Path
ROOT=Path('/Users/yuxianqi/Project/qlib');sys.path.insert(0,str(ROOT));os.environ['MLFLOW_ALLOW_FILE_STORE']='true'
TMP=Path(__file__).resolve().parent
EID='train-data/dft-specialists-20261108-v1'
OLD=ROOT/'backtest/experiments/models/train-data/dft-specialists-20261108-v1'
PREVIOUS=OLD/'extensions/style-es-20261109'
PREV_FW=OLD/'extensions/forward-spread-20261112'
FROZEN_WEEK=PREV_FW/'stages/weekly-h5'
CAMPAIGN=OLD/'extensions/weekly-h5-four-20261113'
STAGE='weekly-h5-four';STAGES=[STAGE]
BASE=CAMPAIGN/'experts'
STATE=BASE/'docs/expert-state.json';PROGRESS=BASE/'docs/study-progress.json'
V5=ROOT/'backtest/experiments/models/training-target/quantile10-p50-v5'
PRIOR=ROOT/'backtest/experiments/models/training-target/label-grading-p50-20261106-v1'
