VALID=ROOT/'backtest/datasets/regime-adapt-cache/shared-v1/validation/50fd959518b0bbf3692afc5f35bbc2a56fa801adc49c79018d736b47e53d2fe7/manifest.json'
TARGET=CAMPAIGN/'data/h5-quantile10.pkl'
TARGET_AUDIT=CAMPAIGN/'docs/h5-target.json'
PROVIDER=ROOT/'backtest/result/20261103_h20_causal_inputs/evaluation-provider'
DATES=ROOT/'backtest/configs/regime-adapt/train_dates_v1.csv'
WEIGHTS=ROOT/'backtest/configs/regime-adapt/day_weights_m0_v1.csv'
LEGACY=ROOT/'backtest/experiments/strategies/topk-dropout/v2-top5-hold-f100/variants/bt-v5/configs/monthly_regime_labels_eval_window_v1.csv'
REGIME=FROZEN_WEEK/'data/date-labels.csv'
BUNDLE_ROOT=ROOT/'backtest/result/20261113_weekly_h5_four';BUNDLE=BUNDLE_ROOT
SEEDS=[42,1000,2000,3000,4000];STYLES=['D','F','T','P'];VARIANTS=['ALL',*STYLES];CONTROLS=['v5','old-D','old-F','old-T'];EVALUATIONS=[*CONTROLS,*VARIANTS]

def read(p):return json.loads(Path(p).read_text())
def write(p,d):
    p=Path(p);p.parent.mkdir(parents=True,exist_ok=True);q=p.with_suffix(p.suffix+'.tmp');q.write_text(json.dumps(d,ensure_ascii=False,indent=2,allow_nan=False)+'\n');q.replace(p)
def fingerprint(p):
    p=Path(p).resolve()
    with p.open('rb') as f:s=hashlib.file_digest(f,'sha256').hexdigest()
    return {'path':str(p.relative_to(ROOT)) if p.is_relative_to(ROOT) else str(p),'sha256':s,'size':p.stat().st_size}
def check(r):
    p=Path(r['path']);p=p if p.is_absolute() else ROOT/p;a=fingerprint(p)
    assert (a['sha256'],a['size'])==(r['sha256'],r['size']),f'input drift: {p}'
def save_source(p):
    p=Path(p).resolve();out=BASE/'docs'/('adapter-'+p.stem+'.json');d={'source':fingerprint(p),'source_text':p.read_text(),'purpose':'Task-only adapter; source retained as audit, executable removed at closure.'}
    if out.exists():assert read(out)==d,'executed source drift: '+str(p)
    else:write(out,d)
def hash_array(a):
    h=hashlib.sha256()
    for i in range(0,len(a),8192):h.update(a[i:i+8192].tobytes(order='C'))
    return h.hexdigest()
def digest(d):return hashlib.sha256(json.dumps(d,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode()).hexdigest()
def save_state(s):
    s=dict(s);s.pop('checksum',None);s['checksum']=digest(s);write(STATE,s)
def state():
    s=read(STATE);c=s.pop('checksum');assert digest(s)==c,'state checksum mismatch';s['checksum']=c;return s
def current_baseline():
    from backtest.scripts.maintenance.experiment_harness import _baseline
    return _baseline(ROOT,'all_a_model')
def day_labels():
    import pandas as pd
    return pd.read_csv(REGIME,index_col=0,parse_dates=True)['style4']
def day_map(dates,labels):
    import pandas as pd
    dates=pd.DatetimeIndex(dates)
    assert labels.index.is_unique and labels.index.is_monotonic_increasing
    out=labels.reindex(dates);assert out.notna().all(),'missing daily style labels'
    assert set(out)<=set(STYLES);return pd.Series(out.to_numpy(),index=dates)
def install_mapping():
    from backtest.scripts.evaluate import eval_ic_multi_pool as ev
    ev.day_regime_map=day_map
def scored_days(variant):
    return int(read(BASE/'configs/prepared-inputs.json')['eval_day_counts'][variant])

CONTRACT=CAMPAIGN/'configs/contract.json'
LOCKED=CAMPAIGN/'docs/stage-state.json'
STAGE_INPUTS=BASE/'configs/prepared-inputs.json'

def verify_lock():
    lock=read(LOCKED)
    assert lock['status']=='active' and lock['contract']['sha256']==fingerprint(CONTRACT)['sha256']
    assert read(FROZEN_WEEK.parent.parent/'docs/expert-state.json')['status']=='closed'
    return lock

def checked(s):
    verify_lock()
    assert s['status']=='active' and time.time()<s['deadline']
    assert digest(current_baseline())==s['baseline_digest']
    for r in s['inputs']:check(r)
    return s

def harness(action,event=None):
    if action=='status':return state()
    if action=='check':return checked(state())
    assert action=='event' and isinstance(event,dict)
    with (STATE.parent/'expert-state.lock').open('a+') as guard:
        fcntl.flock(guard,fcntl.LOCK_EX);s=state();kind=event['type']
        if kind=='fit_start':
            checked(s); assert not any(j['outcome']=='running' for j in s['jobs'].values())
            job=event['job_id']; assert job not in s['jobs'] and event['seed'] in SEEDS and event['variant'] in VARIANTS
            prior=[j for j in s['jobs'].values() if (j['stage'],j['variant'],j['seed'])==(STAGE,event['variant'],event['seed'])]
            assert len(s['jobs'])<s['max_model_fit_starts']
            if prior:
                assert prior[-1]['outcome']=='failed' and event['retry_of']==prior[-1]['job_id']
                assert sum('retry_of' in j for j in s['jobs'].values())<4
            s['jobs'][job]={**event,'kind':'model','stage':STAGE,'outcome':'running','pid':os.getpid(),'started_at':time.time()}
        elif kind=='fit_result':
            j=s['jobs'][event['job_id']]
            assert j['outcome']=='running' and event['outcome'] in ('succeeded','failed')
            j.update(outcome=event['outcome'],finished_at=time.time(),evidence=event['evidence'])
        elif kind=='freeze':
            checked(s);known={x['path']:x for x in s['inputs']}
            for p in event['paths']:
                r=fingerprint(ROOT/p if not Path(p).is_absolute() else p)
                if r['path'] in known:assert r==known[r['path']]
                else:s['inputs'].append(r)
        elif kind=='stage_status':
            s['stages'][STAGE].update(event['values'])
        elif kind=='close':
            assert len([j for j in s['jobs'].values() if j['outcome']=='succeeded'])==25
            assert all(s['stages'][st].get('verified') for st in STAGES)
            s['status']='closed'
        elif kind!='note':
            raise ValueError(kind)
        s['revision']+=1;s['events'].append({'revision':s['revision'],'at':time.time(),**event});save_state(s);return state()
